using System;using System.IO;using System.Linq;using System.Diagnostics;using V15Voice;
public static class CommunityVoiceRealTests {
 static int n;static void Check(bool b,string text){if(!b)throw new Exception(text);Console.WriteLine("PASS "+text);n++;}
 public static void Main(string[] args){string root=Path.GetFullPath(args[0]),folder=Path.Combine(Path.GetTempPath(),"V15 Adam thật "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var timer=Stopwatch.StartNew();
  using(var e=new KokoroEngine{Root=root,Kind=EngineKind.Rvc,ModelFolder=CommunityVoices.AdamFolder,VoiceName="Adam · RVC cộng đồng",DeviceMode="cpu",Threads=2}){
   e.CheckFiles();if(args.Contains("--cancel-only")){bool requested=false,cancelled=false;e.ActivityChanged=message=>{if(!requested&&message.Contains("Đang chuyển giọng Adam RVC")){requested=true;e.Cancel();}};string target=Path.Combine(folder,"cancel.wav");try{e.Generate("This is the conversion that will be stopped.",1,target);}catch(OperationCanceledException){cancelled=true;}Check(requested&&cancelled,"Stop cancels real RVC worker during conversion through owner forwarding");Check(!File.Exists(target)&&!Directory.GetFiles(folder,"*.rvc-*.wav").Any(),"Stopped real RVC leaves no final/intermediate audio");Console.WriteLine("TOTAL REAL COMMUNITY CANCEL "+n+" passed.");return;}var w=e.Generate("This small detail changes the whole story.",1,Path.Combine(folder,"trial.wav"));Check(w.Rate==32000&&w.Duration>1&&w.Duration<10,"Real native Kokoro → real RVC produces speech WAV");Check(e.DeviceInfo.Contains("RVC")&&e.DeviceInfo.Contains("Michael"),"Device report identifies RVC and its actual base speech");Check(!Directory.GetFiles(folder,"*.rvc-*.wav").Any(),"Intermediate base speech cleaned after conversion");
   var cues=Scripts.ParseSrt("1\n00:00:00,200 --> 00:00:03,400\nThis small detail changes the whole story.\n");string source=Path.Combine(folder,"story.srt");File.WriteAllText(source,Scripts.ToSrt(cues));string sourceHash=StateFiles.Hash(source);var o=new RenderOptions{Locked=true,Breathing=BreathMode.None,Punctuation=PunctuationMode.Auto,SlowShort=false,MinSpeed=.9,MaxSpeed=1.3,ReportContext=new VoiceReportContext{SourcePath=source,VoiceKey="C:adam_rvc"}};string output=Renderer.Render(cues,e,o,OutputFiles.Beside(source),(i,m)=>{});Check(File.Exists(output)&&FinalAudio.PcmFrames(output)==81600,"Real locked SRT matches requested total frames");Check(cues[0].Natural>0&&cues[0].Actual>0&&cues[0].Speed<=1.3,"Timeline uses measured converted waveform and speed bounds");Check(StateFiles.Hash(source)==sourceHash,"Real render preserves source SRT");
   var prose=LongText.Parse("The story starts here. Look closely at the details.");var po=new RenderOptions{Locked=false,Prose=true,Breathing=BreathMode.None,Punctuation=PunctuationMode.Auto,ReportContext=new VoiceReportContext{SourcePath=Path.Combine(folder,"story.txt"),VoiceKey="C:adam_rvc"}};string txt=Renderer.Render(prose,e,po,Path.Combine(folder,"text.wav"),(i,m)=>{});Check(File.Exists(txt)&&Wave.Read(txt).Duration>2,"Real RVC works through natural TXT workflow");
   var vc=new VoiceSettings{Key="C:adam_rvc",Mode=0,Device="cpu",Normalize=false,Breathing=2,Speed=1,MinSpeed=.9,MaxSpeed=1.3,Slow=false};var session=RepairSession.Open(source,Scripts.ParseSrt(File.ReadAllText(source)),folder,false);session.Settings=vc.Xml().ToString();var take=AudioRepair.Trial(session,session.Parts[0],e,AudioRepair.Options(session.Settings),"C:adam_rvc",session.Sources,"A");Check(take.Success&&take.Voice.Contains("RVC")&&take.Natural>0,"Real RVC A/B candidate measures converted speech");session.Parts[0].Selected=take;string merged=AudioRepair.Merge(session,e,AudioRepair.Options(session.Settings),(i,m)=>{});Check(FinalAudio.PcmFrames(merged)==81600&&File.Exists(output),"A/B merges exact timeline and preserves earlier output");
  }Console.WriteLine("TOTAL REAL COMMUNITY "+n+" passed in "+timer.Elapsed.TotalSeconds.ToString("0.0")+"s. CPU Linux; physical Windows/CUDA not tested. Fixtures: "+folder);
 }
}
